-- 0001_core_schema.sql
-- Kernel tables shared by every module (specification §4.3, §4.4 "Operations" and "Reliability",
-- §4.9 idempotency, §4.12 outbox/inbox). Every operational record carries organization scope.
--
-- Conventions for all later migrations (see CLAUDE.md):
--   * ids are uuid, generated by the application (time-ordered v7) — never serial.
--   * every org-scoped table has organization_id uuid not null references organizations(id).
--   * org-scoped references between tables use composite foreign keys on (organization_id, <id>)
--     so a row can never point at another organization's record.
--   * sensitive editable records carry `revision integer not null default 1`.
--   * timestamps are timestamptz; facility-local times are derived from facilities.timezone.
--   * money is bigint minor units next to a currency text column.

create extension if not exists btree_gist;

create or replace function touch_updated_at() returns trigger
language plpgsql as $$
begin
  new.updated_at := now();
  return new;
end
$$;

create or replace function forbid_mutation() returns trigger
language plpgsql as $$
begin
  raise exception 'table % is append-only', tg_table_name using errcode = 'restrict_violation';
end
$$;

create table organizations (
  id uuid primary key,
  slug text not null unique,
  name text not null,
  status text not null default 'active' check (status in ('active', 'suspended', 'archived')),
  settings jsonb not null default '{}'::jsonb,
  revision integer not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create trigger organizations_touch before update on organizations
  for each row execute function touch_updated_at();

create table facilities (
  id uuid primary key,
  organization_id uuid not null references organizations(id),
  slug text not null,
  name text not null,
  timezone text not null,
  address jsonb,
  status text not null default 'active' check (status in ('active', 'closed', 'archived')),
  settings jsonb not null default '{}'::jsonb,
  revision integer not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (organization_id, slug),
  unique (organization_id, id)
);
create trigger facilities_touch before update on facilities
  for each row execute function touch_updated_at();

-- Audit (append-only). Actor is a principal snapshot; child information must never be written here.
create table audit_records (
  id uuid primary key,
  organization_id uuid not null references organizations(id),
  occurred_at timestamptz not null default now(),
  actor jsonb not null,
  action text not null,
  target_type text not null,
  target_id text not null,
  before_revision integer,
  after_revision integer,
  reason text,
  correlation_id text,
  operation_id uuid,
  details jsonb not null default '{}'::jsonb
);
create index audit_records_target_idx on audit_records (organization_id, target_type, target_id, occurred_at desc);
create index audit_records_time_idx on audit_records (organization_id, occurred_at desc);
create trigger audit_records_append_only before update or delete on audit_records
  for each row execute function forbid_mutation();

-- Durable operations: the readable outcome of an asynchronous or multi-step command (GET /v1/operations/{id}).
create table operations (
  id uuid primary key,
  organization_id uuid not null references organizations(id),
  kind text not null,
  status text not null check (status in ('pending', 'running', 'succeeded', 'failed', 'recovery_required', 'compensated')),
  requested_by jsonb not null,
  correlation_id text,
  input jsonb,
  result jsonb,
  error jsonb,
  revision integer not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  completed_at timestamptz
);
create index operations_status_idx on operations (organization_id, status, created_at desc);
create trigger operations_touch before update on operations
  for each row execute function touch_updated_at();

-- Idempotency (§4.9): same key + same payload replays; same key + different payload conflicts.
create table idempotency_keys (
  organization_id uuid not null references organizations(id),
  scope_key text not null,
  idempotency_key text not null,
  request_hash text not null,
  status text not null check (status in ('in_progress', 'completed')),
  response_status integer,
  response_body jsonb,
  operation_id uuid references operations(id),
  created_at timestamptz not null default now(),
  completed_at timestamptz,
  expires_at timestamptz not null,
  primary key (organization_id, scope_key, idempotency_key)
);
create index idempotency_keys_expiry_idx on idempotency_keys (expires_at);

-- Transactional outbox (§4.12): written in the same transaction as the business change.
create table outbox_events (
  id uuid primary key,
  organization_id uuid not null references organizations(id),
  event_type text not null,
  aggregate_type text not null,
  aggregate_id text not null,
  payload jsonb not null,
  occurred_at timestamptz not null default now(),
  correlation_id text,
  causation_id text,
  operation_id uuid,
  status text not null default 'pending' check (status in ('pending', 'dispatched', 'dead')),
  available_at timestamptz not null default now(),
  attempts integer not null default 0,
  max_attempts integer not null default 10,
  last_error text,
  locked_by text,
  locked_until timestamptz,
  dispatched_at timestamptz,
  failure_owner text
);
create index outbox_events_pending_idx on outbox_events (available_at) where status = 'pending';
create index outbox_events_aggregate_idx on outbox_events (organization_id, aggregate_type, aggregate_id, occurred_at);

-- Inbox for external provider events (webhooks): authenticated, durably recorded, duplicate-tolerant.
create table inbox_events (
  id uuid primary key,
  provider text not null,
  provider_event_id text not null,
  organization_id uuid references organizations(id),
  event_type text not null,
  payload jsonb not null,
  signature_verified boolean not null default false,
  received_at timestamptz not null default now(),
  status text not null default 'received' check (status in ('received', 'processed', 'failed', 'ignored', 'dead')),
  attempts integer not null default 0,
  last_error text,
  processed_at timestamptz,
  unique (provider, provider_event_id)
);
create index inbox_events_pending_idx on inbox_events (received_at) where status in ('received', 'failed');

-- One logical business effect per handler per event, even when delivery repeats.
create table event_consumptions (
  handler text not null,
  event_id uuid not null,
  consumed_at timestamptz not null default now(),
  primary key (handler, event_id)
);

create table job_attempts (
  id uuid primary key,
  organization_id uuid references organizations(id),
  source text not null check (source in ('outbox', 'inbox', 'scheduled')),
  source_id uuid not null,
  handler text not null,
  attempt_number integer not null,
  worker_id text not null,
  started_at timestamptz not null default now(),
  finished_at timestamptz,
  outcome text check (outcome in ('succeeded', 'failed', 'skipped')),
  error text,
  correlation_id text
);
create index job_attempts_source_idx on job_attempts (source, source_id, attempt_number);

-- Operational exceptions surfaced in the Today workspace (SPK-UX-006). Closing an exception never
-- resolves the underlying record; modules keep the authoritative state on their own tables.
create table operational_exceptions (
  id uuid primary key,
  organization_id uuid not null references organizations(id),
  facility_id uuid,
  category text not null,
  severity text not null check (severity in ('info', 'warning', 'high', 'critical')),
  title text not null,
  affected_type text,
  affected_id text,
  owner_queue text not null,
  status text not null default 'open' check (status in ('open', 'acknowledged', 'resolved', 'closed')),
  opened_at timestamptz not null default now(),
  deadline_at timestamptz,
  acknowledged_at timestamptz,
  resolved_at timestamptz,
  closed_at timestamptz,
  resolution jsonb,
  details jsonb not null default '{}'::jsonb,
  dedupe_key text,
  revision integer not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  foreign key (organization_id, facility_id) references facilities (organization_id, id)
);
create unique index operational_exceptions_dedupe_idx on operational_exceptions (organization_id, dedupe_key)
  where dedupe_key is not null and status in ('open', 'acknowledged');
create index operational_exceptions_open_idx on operational_exceptions (organization_id, status, severity, opened_at)
  where status in ('open', 'acknowledged');
create trigger operational_exceptions_touch before update on operational_exceptions
  for each row execute function touch_updated_at();
